/* Reap completions from one NVMe CQ (phase starts at 1). */
unsigned n = 0;
while (((cq[head].dw3 >> 16) & 1) == phase) {
    uint16_t cid    = cq[head].dw3 & 0xffff;   /* command id   */
    uint16_t status = cq[head].dw3 >> 17;      /* 0 = success  */
    complete(cid, status);
    if (++head == qsize) { head = 0; phase ^= 1; }
    n++;
}
if (n) mmio_write32(cq_head_doorbell, head);   /* free the slots */
